#include "engine/sky/Systems.hpp"
#include <nlohmann/json.hpp>
#include <fstream>
#include <algorithm>
#include <cmath>
namespace Engine::Sky {
namespace {
bool Valid(const WeatherParameters& p){Settings s;s.weather.current=s.weather.target=p;return bool(Validate(s));}
WeatherParameters Blend(const WeatherParameters& a,const WeatherParameters& b,float t){auto mix=[&](float x,float y){return std::lerp(x,y,t);};return {mix(a.coverage,b.coverage),mix(a.type,b.type),mix(a.precipitation,b.precipitation),{mix(a.wind.x,b.wind.x),mix(a.wind.y,b.wind.y),mix(a.wind.z,b.wind.z)},mix(a.fogDensity,b.fogDensity),mix(a.wetness,b.wetness)};}
}
Result LoadWeatherPresets(const std::filesystem::path& path,std::vector<WeatherPreset>& output){try{std::ifstream file(path);if(!file)return Result::Failure("Cannot open weather presets");nlohmann::json json;file>>json;if(json.at("version")!=1)return Result::Failure("Unsupported weather presets version");std::vector<WeatherPreset> next;for(const auto& item:json.at("presets")){WeatherPreset preset;preset.name=item.at("name");const auto& p=item.at("parameters");preset.parameters={p.at("coverage"),p.at("type"),p.at("precipitation"),{p.at("wind").at(0),p.at("wind").at(1),p.at("wind").at(2)},p.at("fogDensity"),p.at("wetness")};if(preset.name.empty()||!Valid(preset.parameters)||std::any_of(next.begin(),next.end(),[&](auto& old){return old.name==preset.name;}))return Result::Failure("Invalid/duplicate weather preset");next.push_back(std::move(preset));}if(next.empty())return Result::Failure("No weather presets");output=std::move(next);return Result::Success();}catch(const std::exception& e){return Result::Failure(std::string("Weather presets: ")+e.what());}}
Result WeatherSystem::Transition(WeatherState& state,const WeatherParameters& target,float duration){if(!Valid(state.current)||!Valid(target)||!std::isfinite(duration)||duration<0||duration>86400)return Result::Failure("Invalid weather transition");m_start=state.current;m_target=target;m_duration=duration;m_elapsed=0;m_active=duration>0;state.target=target;state.duration=duration;state.transitioning=m_active?1u:0u;if(!m_active)state.current=target;return Result::Success();}
Result WeatherSystem::Update(WeatherState& state,VolumetricClouds& clouds,double seconds){if(!std::isfinite(seconds)||seconds<0)return Result::Failure("Invalid weather timestep");if(!Valid(state.current)||!Valid(state.target)||!std::isfinite(state.duration)||state.duration<0||state.duration>86400)return Result::Failure("Invalid weather state");if(state.transitioning&&(!m_active||state.target!=m_target||state.duration!=m_duration)){auto r=Transition(state,state.target,state.duration);if(!r)return r;}if(!state.transitioning)m_active=false;if(m_active){m_elapsed=std::min(double(m_duration),m_elapsed+seconds);float t=float(m_elapsed/m_duration);t=t*t*(3-2*t);state.current=Blend(m_start,m_target,t);if(m_elapsed>=m_duration){state.current=m_target;state.transitioning=0;m_active=false;}}clouds.coverage=state.current.coverage;clouds.typeBlend=state.current.type;clouds.wind=state.current.wind;return Result::Success();}
}
